def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing callable that saves results in a cache.

    Arguments:
        cache (dict): The cache object in which to save results.
        key: A function that generates a cache key for a given argument tuple.
        lock: An optional lock object for synchronizing access to the cache.

    Returns:
        A new callable that wraps the decorated function and saves its results in the cache.

    Example:
        ```
        @cachedmethod(cache={})
        def fibonacci(n):
            if n <= 1:
                return n
            else:
                return fibonacci(n-1) + fibonacci(n-2)

        assert fibonacci(10) == 55  # Fibonacci number
        ```
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # generate the cache key using the argument values and the `key` function
            cache_key = key(*args, **kwargs) if key else id(args)

            # check if the result is already in the cache
            if cache_key in cache:
                result = cache[cache_key]
            else:
                # if the result is not in the cache, compute it and save it to the cache
                # using the `lock` object, if specified, for synchronized access
                if lock:
                    with lock:
                        result = cache[cache_key] = func(*args, **kwargs)
                else:
                    result = cache[cache_key] = func(*args, **kwargs)

            return result

        return wrapper

    return decorator

