            pre += f"\n{indent * ' ' * (self.indent_level() + 1)}<Attr name={quoteattr(n)}>{v}</Attr>"
    pre += f"\n{indent * ' ' * (self.indent_level())}</{self.get_type()}>"
    return pre

def quoteattr(s):
    s = repr(s)
    if s[0] == "'":
