def merge_node_values(node1, node2):
    # handle case where both nodes are integers
    if isinstance(node1, ruamel.yaml.nodes.ScalarNode) and isinstance(node2, ruamel.yaml.nodes.ScalarNode) and node1.tag == 'tag:yaml.org,2002:int' and node2.tag == 'tag:yaml.org,2002:int':
        return node2

    # handle case where both nodes are strings
    if isinstance(node1, ruamel.yaml.nodes.ScalarNode) and isinstance(node2, ruamel.yaml.nodes.ScalarNode) and node1.tag == 'tag:yaml.org,2002:str' and node2.tag == 'tag:yaml.org,2002:str':
        return node2

    # handle case where both nodes are mappings
    if isinstance(node1, ruamel.yaml.nodes.MappingNode) and isinstance(node2, ruamel.yaml.nodes.MappingNode):
        result = []
        for key, value in node1.value:
            matching_keys = [node for node in node2.value if node[0] == key]
            if matching_keys:
                merged_value = merge_node_values(matching_keys[0][1], value)
                result.append((key, merged_value))
            else:
                result.append((key, value))

        for key, value in node2.value:
            if key not in [node[0] for node in result]:
                result.append((key, value))

        return ruamel.yaml.nodes.MappingNode(tag=ruamel.yaml.YAML().default_flow_style, value=result)

    # handle case where node1 and node2 are of different types
    if node1.tag != node2.tag:
        return node2

    # handle case where node1 and node2 are the same type but not handled above
    raise NotImplementedError("Cannot merge nodes with values of type %s" % node1.tag)

