def parse_subparser_arguments(unparsed_arguments, subparsers, suppressed_unrecognized_error=False):
    # Set up dict for result
    parsed_arguments = {}
    for subparser_name, subparser in subparsers.items():
        # If no arguments available, add empty namespace
        if not unparsed_arguments:
            parsed_arguments[subparser_name] = argparse.Namespace()
        else:
            # Attempt to parse arguments
            try:
                parsed_arguments[subparser_name] = subparser.parse_args(unparsed_arguments)
            except argparse.ArgumentError as e:
                # If argument error is unrecognized, print usage and exit
                if e.code == argparse.ArgumentError.UNRECOGNIZED_ARGS:
                    subparser.usage(subparser_name)
                    exit(1)
                # Otherwise, reraise the exception
                raise
        # Remove any arguments already parsed
        unparsed_arguments = [arg for arg in unparsed_arguments if arg not in parsed_arguments[subparser_name]._get_kwargs()]

    return parsed_arguments, unparsed_arguments

