def deep_merge_nodes(nodes):
    merged = {}
    for node in nodes:
        if node[0] in merged:
            # merge duplicate keys
            merged[node[0]] = _deep_merge(merged[node[0]], node[1])
        else:
            # add non-duplicate keys
            merged[node[0]] = node[1]
    return [tuple(x) for x in merged.items()]

def _deep_merge(a, b):
    if type(a) is MappingNode and type(b) is MappingNode:
        # deep merge corresponding mappings
        for key, val in a.items():
            if key in b:
                b[key] = _deep_merge(val, b[key])
        return b
    elif type(a) in [ScalarNode, TypeNode] and type(b) in [ScalarNode, TypeNode]:
        # replace non-mapping values
        return b
    else:
        raise TypeError("Unsupported node type.")
