def parse_wikipedia_dumps(*filenames, summary=True,  header=False, min_len=0, error_bad_unicode=False, **kwargs):
    # Initialize a Wikipedia dump parser
    parser = WikipediaDumpParser(kwargs)

    # Define a function to handle each article
