import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    err_logs = []
    for filename in config_filenames:
        try:
            with open(filename, "r") as f:
                configs[filename] = json.loads(f.read())
        except FileNotFoundError:
            err_logs.append(logging.LogRecord(logging.ERROR, "File {} not found".format(filename)))
        except json.JSONDecodeError:
            err_logs.append(logging.LogRecord(logging.ERROR, "Could not parse JSON from file {}".format(filename)))
    if overrides:
        for k, v in overrides.items():
            if k in configs:
                configs[k].update(v)
            else:
                err_logs.append(logging.LogRecord(logging.ERROR, "Overriding non-existent key {}".format(k)))
    if resolve_env:
        for config in configs.values():
            config = apply_env_overrides(config, resolve_env)
    return configs, err_logs

def apply_env_overrides(config, resolve_env):
